---更新home数据
---@param activityDojo ActivityDojo
function DreamAdventuresMgr:UpdateHomeData(activityDojo)
    if not activityDojo then return end

    GameUtils.Request(Interfaces.DreamAdventuresHome, {activityUuid = activityDojo.id}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            Events.Broadcast(Constants.EventNames.DreamAdventuresHomeDataUpdate)
            return
        end
        
        self:GetDreamAdventuresComponent():Initial(response.data)
        self:StartTimer()
        Events.Broadcast(Constants.EventNames.DreamAdventuresHomeDataUpdate)
    end)
end

