---播放剧情
function DreamAdventuresMgr:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end

    self:PlayingPlot(plotIds, endCb)
end

---剧情播放中
function DreamAdventuresMgr:PlayingPlot(plotIds, endCb)
    local co = cs_coroutine.start(function()
        for _, id in ipairs(plotIds) do
            local wait = true
            local plotGo = nil
            local lastDialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.ActivityDreamAdventuresMain)
            ChapterUtils.ProcessChapter(checkNumber(id), function(go)
                if isNotNull(lastDialog) then
                    lastDialog.transform.localPosition = Vector3(9999, 9999, 9999)
                end
                URPCameraController:SetMainCameraActive(false)
                UINavigationBarRoot.Instance:SetActive(false)
                plotGo = go
            end, function()
                --所有的播完结束
                if isNotNull(lastDialog) then
                    lastDialog.transform.localPosition = Vector3(0, 0, 0)
                end
                URPCameraController:SetMainCameraActive(true)
                UINavigationBarRoot.Instance:SetActive(true)
                wait = false
            end)

            while wait do
                coroutine.yield()
            end

            KTool.SafeDelete(plotGo)

            --dispose
            coroutine.yield()
        end

        self:PlayBGM()
        if endCb then
            endCb()
        end
    end)
end

---显示活动体力tips
function DreamAdventuresMgr:ShowTipsCountDown(targetNode, title, description, rare, id, isShowNumText)
    ResourceModule.LoadGameObjectAsync("Prefabs/ActivityDreamAdventures12000801/ActivityDreamAdventuresStaminaTipsCountdown.prefab", function(go)
        if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
            go.name = "StaminaTipsCountdown"
            if not KTool.IsNull(go) and not KTool.IsNull(targetNode) then
                local script = GetLuaBehaviour(go, DreamAdventuresConstants.ScrPath.StaminaTipsCountDown)
                if not KTool.IsNull(script) then
                    script.Env:RefreshBoardByContent(title, description, rare, id, isShowNumText)
                    script.Env:FixBoardPosition(targetNode)
                end
            end
        end
    end, true, UIModule.RootCanvas.transform)
end

---购买活动体力
function DreamAdventuresMgr:BuyActivityHp()
    local activityDojo = self:GetActivityDojo()
    if not self:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local maxLimit = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.HP_UP_LIMIT)
    local num = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.BUY_NUM)
    local consumeGoodsId = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.BUY_CONSUME_ITEM)
    local consumeGoodsNum = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.BUY_CONSUME_ITEM_NUM)
    local buyTimes = checkInt(self:GetDreamAdventuresDojo().dailyBuyHpTimes)
    local maxBuyLimit = DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.BUY_DAILY_TIME_LIMIT)
    local maxBuyNum = 1
    if checkInt(buyTimes) >= checkInt(maxBuyLimit) then
        maxBuyNum = 0
    end
    local consumeNums = parse_strings(consumeGoodsNum)
    local consumeNum = consumeNums[buyTimes + 1] or consumeNums[#consumeNums]
    local prices = {{currency = checkInt(consumeGoodsId), current = checkInt(consumeNum)}}
    local activityTips = localize('今日剩余兑换次数: _num_', {_num_ = checkInt(maxBuyLimit) - buyTimes})
    local consume = {goodsId = consumeGoodsId, num = consumeNum}

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
        goodsId        = self:GetActivityHPId(),
        goodsNum       = num,
        isShowNum      = true,
        maxHaveNum     = checkInt(maxLimit),
        prices         = prices,
        maxBuyNum      = maxBuyNum,
        activityTips   = activityTips,
        buyCb          = function (price, buyNum)
            GameUtils.Request(Interfaces.DreamAdventuresBuyHp, {consume = table.serialize(consume), activityUuid = activityDojo.id}, function(request, response)
                local showRewards = clone(response.data.rewards)
                table.insert(response.data.rewards, {
                    goodsId = consumeGoodsId,
                    num = -consumeNum
                })
                GoodsUtils.DrawRewards(response.data.rewards, true)
                local dojo = self:GetDreamAdventuresDojo()
                dojo.hpData = checkTable(response.data.hpInfo)
                dojo.dailyBuyHpTimes = checkInt(self:GetDreamAdventuresDojo().dailyBuyHpTimes) + 1
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = showRewards } })
            end)
        end
    }})
end

---开启定时器
function DreamAdventuresMgr:StartTimer()
    self:CloseTimer()
    self.timer = CDTimerModule.GetInstance():AddCD(1, function(_, _, delta)
        local dojo = self:GetDreamAdventuresDojo()
        -- 体力已经恢复满，停止倒计时
        if self:IsHPFull() then
            dojo.hpData.lastCdTime = 0
            self:BroadcastHPChangeEvent(true, 0, 0)
            self:CloseTimer()
            return
        end

        if dojo.hpData.lastCdTime <= 0 then
            dojo.hpData.lastCdTime = checkNumber(DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.RESTORE_HP_INTERVAL))
        end
        self:SubCDTime(delta)

    end, CountDownTime, true, true)
end

---判断活动体力是否回满
function DreamAdventuresMgr:IsHPFull()
    local ownCount = self:GetActivityHP()
    local max = checkNumber(DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.HP_UP_LIMIT))

    return ownCount >= max
end

---广播hp变动事件
function DreamAdventuresMgr:BroadcastHPChangeEvent(isFull, cd, totalCD)
    if Events.HasListener(Constants.EventNames.DreamAdventuresActivityHpChange) then
        Events.Broadcast(Constants.EventNames.DreamAdventuresActivityHpChange, isFull, cd, totalCD)
    end
end

---定时器处理
function DreamAdventuresMgr:SubCDTime(delta)
    local dojo = self:GetDreamAdventuresDojo()
    dojo.hpData.lastCdTime = checkNumber(dojo.hpData.lastCdTime) - checkNumber(delta)
    -- 通知注册者数值发生了变化
    local goodsNum = GoodsUtils.GetThingNo(self:GetActivityHPId())
    local max = checkNumber(DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.HP_UP_LIMIT))
    local hpRecoverSeconds = checkNumber(DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.RESTORE_HP_INTERVAL))
    local recoveryHpPerTime = checkNumber(DreamAdventuresUtils.GetConfigParamsById(DreamAdventuresConstants.ParamsDefine.RESTORE_NUM))
    self:BroadcastHPChangeEvent(false, checkInt(dojo.hpData.lastCdTime), checkInt(dojo.hpData.lastCdTime + (max - goodsNum - 1) * checkInt(hpRecoverSeconds)))
    if dojo.hpData.lastCdTime < 0 then
        -- 开始恢复体力
        local mod = (math.abs(dojo.hpData.lastCdTime) - 1) % recoveryHpPerTime    -- 溢出mod秒
        local left = (math.abs(dojo.hpData.lastCdTime) - 1) / recoveryHpPerTime   -- 溢出left体力
        local recoverCount = (left + 1) * recoveryHpPerTime

        --printInfo("CHANG DEBUG：实际恢复的体力:" .. checkString(recoverCount))
        GoodsUtils.DrawRewards({
            {
                goodsId = self:GetActivityHPId(),
                num = recoverCount
            }
        }, true)

        -- 重置倒计时
        dojo.hpData.lastCdTime = hpRecoverSeconds - mod
        self:StartTimer()
    end
end

---移除定时器
function DreamAdventuresMgr:CloseTimer()
    if isNotNull(self.timer) then
        CDTimerModule.GetInstance():RemoveCD(self.timer)
        self.timer = nil
    end
end

---IsActive @ 判断活动是否开启
function DreamAdventuresMgr:IsActive()
    local activityDojo = self:GetActivityDojo()
    if isNull(activityDojo) then
        return false
    end
    local startTime = checkNumber(activityDojo.startTime)
    local endTime = checkNumber(activityDojo.endTime)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTimeWithTimeZone()
    return curTime >= startTime and curTime <= endTime
end

function DreamAdventuresMgr:IsClose()
    local activityDojo = self:GetActivityDojo()
    if isNull(activityDojo) then
        return false
    end
    local startTime = checkNumber(activityDojo.startTime)
    local closeTime = checkNumber(activityDojo.closeTime)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTimeWithTimeZone()
    return curTime >= startTime and curTime <= closeTime
end

---检查活动是否开启
function DreamAdventuresMgr:CheckActive()
    local active = self:IsActive()
    if not active then
        GameUtils.Toast(localize("活动已结束"))
    end
    
    return active
end

function DreamAdventuresMgr:CheckClose()
    local active = self:IsClose()
    if not active then
        GameUtils.Toast(localize("活动已结束"))
    end

    return active
end

---检查节点是否达到开启时间
function DreamAdventuresMgr:CheckSiteOpenTime(unlockCountdown)
