---检查入口按钮是否解锁
---@param btnType DreamAdventuresConstants.EntryBtnType
function DreamAdventuresMgr:CheckEntryBtnUnlock(btnType)
    local conf = self:GetEntryBtnConf(btnType) or {}
    if checkInt(conf.unlockLevel) == 0 then return true end

    local mainQuestId = self:GetMainQuestId()
    return mainQuestId >= checkInt(conf.unlockLevel)
end

---检查材料是否解锁
function DreamAdventuresMgr:CheckMaterialUnlock(materialId)
    local ids = self:GetModulationMaterialIds()
    
    local isUnlock = false
    for i, v in ipairs(ids) do
        if checkInt(v) == checkInt(materialId) then
            isUnlock = true
            break
        end
    end
    return isUnlock
end

