---获取全服奖励列表
function DreamAdventuresMgr:GetAllRewardsList()
    local vo = CfUtils.GetCf(AutoIds.IdSetting6191, "DreamAdventuresAllRewardsVo", true)
    local contentId = self:GetActivityContentId()
    local rewardsList = {}
    for i, v in ipairs(vo) do
        if checkInt(v.activityId) == contentId then
            table.insert(rewardsList, v)
        end
    end
    table.sort(rewardsList, function(a, b)
        return checkInt(a.point) < checkInt(b.point)
    end)
    return rewardsList
end

---获取个人奖励列表
function DreamAdventuresMgr:GetPersonalRewardsList()
    local vo = CfUtils.GetCf(AutoIds.IdSetting6190, "DreamAdventuresPersonalRewardsVo", true)
    local contentId = self:GetActivityContentId()
    local rewardsList = {}
    for i, v in ipairs(vo) do
        if checkInt(v.activityId) == contentId then
            table.insert(rewardsList, v)
        end
    end
    table.sort(rewardsList, function(a, b)
        return checkInt(a.point) < checkInt(b.point)
    end)
    return rewardsList
end

---获取全服奖励进度百分比
function DreamAdventuresMgr:GetAllRewardsPercentage()
    local rewardsList = self:GetAllRewardsList()
    local point = self:GetAllWinePress()
    local max = checkInt(rewardsList[#rewardsList].point)
    local percent = checkInt(math.min(point, max) / max * 1000) / 1000
    return percent
end

