---获取筹备红点状态
function DreamAdventuresMgr:GetPreparationRedPointState()
    -- 奖励优先级最高
    if self:GetPreparationAllRewardsRedPointState() then return 1 end
    if self:GetPreparationPersonalRedPointState() then return 1 end

    -- 其次是卢比
    local events = self:GetRupeeEvent()
    if next(events) then return 2 end

    -- 最后是筹备道具
    local pointId = self:GetActivityPointId()
    local pointNum = GoodsUtils.GetThingNo(pointId)
    if pointNum > 0 then return 3 end
    
    -- 无红点返回0
    return 0
end

---获取筹备全服奖励红点状态
function DreamAdventuresMgr:GetPreparationAllRewardsRedPointState()
    local rewards = self:GetAllRewardsList()
    local point = self:GetAllWinePress()
    local ids = self:GetAllWineRewardIds()
    for _, v in ipairs(rewards) do
        if checkInt(point) >= checkInt(v.point) and not ids[tostring(v.id)] then
            return true
        end
    end
    return false
end

